/** Clasifica la tarea en TaskType (envuelve classifyTaskDetailed). */
export function classifyTask(signals: TaskSignals, opts: TaskClassifierOptions = {}): TaskType {
  return classifyTaskDetailed(signals, opts).taskType;
}

